import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./AuthContext";

const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;

export default function Login() {
  const { saveToken } = useContext(AuthContext);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const canvasRef = React.useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    // Grid settings
    const gridSize = 50;
    let offset = 0;
    let scanY = 0;
    
    // Resize handler
    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);
    
    // Animation loop
    function drawCyberpunkGrid() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      // Perspective grid - horizontal lines
      for (let i = 0; i < 20; i++) {
        const y = canvas.height - (i * gridSize) + offset;
        const scale = 1 - (i / 30);
        
        ctx.beginPath();
        ctx.moveTo(canvas.width * (0.5 - scale/2), y);
        ctx.lineTo(canvas.width * (0.5 + scale/2), y);
        ctx.strokeStyle = `rgba(255, 0, 255, ${0.1 + i * 0.03})`;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      
      // Vertical lines
      for (let i = -10; i < 10; i++) {
        const x = canvas.width / 2 + (i * gridSize);
        
        ctx.beginPath();
        ctx.moveTo(x, canvas.height);
        ctx.lineTo(canvas.width / 2 + (i * gridSize * 0.3), canvas.height - 1000);
        ctx.strokeStyle = `rgba(0, 255, 255, ${0.2 + Math.abs(i) * 0.02})`;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      
      // Glowing scan line
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff00ff';
      ctx.fillStyle = 'rgba(255, 0, 255, 0.3)';
      ctx.fillRect(0, scanY, canvas.width, 2);
      ctx.shadowBlur = 0;
      
      // Random glitch lines
      if (Math.random() > 0.97) {
        const glitchY = Math.random() * canvas.height;
        ctx.fillStyle = `rgba(0, 255, 255, ${Math.random() * 0.5})`;
        ctx.fillRect(0, glitchY, canvas.width, 1);
      }
      
      // Update
      offset = (offset + 1) % gridSize;
      scanY = (scanY + 3) % canvas.height;
      
      requestAnimationFrame(drawCyberpunkGrid);
    }
    
    drawCyberpunkGrid();
    
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  useEffect(() => {
    if (window.google && GOOGLE_CLIENT_ID) {
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleResponse,
      });

      window.google.accounts.id.renderButton(
        document.getElementById("googleSignInDiv"),
        {
          theme: "outline",
          size: "large",
          width: "400",
          text: "continue_with",
          shape: "rectangular",
        }
      );
    }
  }, []);

  const handleGoogleResponse = async (response) => {
    const googleToken = response.credential;
    setIsLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:8000/auth/google", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id_token: googleToken }),
      });

      const data = await res.json();
      if (!res.ok) {
        alert("Google login failed");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please fill in all fields");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.detail || "Invalid credentials");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      width: "100vw",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      background: "#000000",
      padding: "20px",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      position: "relative",
      overflow: "hidden",
      margin: 0
    }}>
      {/* Cyberpunk Grid Canvas */}
      <canvas
        ref={canvasRef}
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none"
        }}
      />

      {/* Ambient glow overlay */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: "radial-gradient(ellipse at center, rgba(255, 0, 255, 0.1) 0%, transparent 70%)",
        pointerEvents: "none"
      }} />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes neonGlow {
          0%, 100% { box-shadow: 0 0 20px rgba(255, 0, 255, 0.5); }
          50% { box-shadow: 0 0 40px rgba(0, 255, 255, 0.5); }
        }
        input:focus {
          outline: none;
          border-color: #ff00ff;
          box-shadow: 0 0 10px rgba(255, 0, 255, 0.5);
        }
        .hover-lift {
          transition: all 0.3s ease;
        }
        .hover-lift:hover {
          transform: translateY(-4px);
          box-shadow: 0 0 30px rgba(255, 0, 255, 0.6), 0 0 60px rgba(0, 255, 255, 0.3);
        }
        button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>

      <div style={{
        width: "480px",
        background: "rgba(0, 0, 0, 0.8)",
        backdropFilter: "blur(10px)",
        padding: "48px",
        borderRadius: "16px",
        boxShadow: "0 0 30px rgba(255, 0, 255, 0.5), inset 0 0 50px rgba(0, 255, 255, 0.1)",
        border: "2px solid rgba(255, 0, 255, 0.5)",
        animation: "fadeIn 0.5s ease-out, neonGlow 3s ease-in-out infinite",
        position: "relative",
        zIndex: 10
      }}
      className="hover-lift">
        
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <h1 style={{
            fontSize: "32px",
            fontWeight: "700",
            color: "#00ffff",
            marginBottom: "8px",
            textShadow: "0 0 20px rgba(0, 255, 255, 0.8), 0 0 40px rgba(255, 0, 255, 0.5)",
            fontFamily: "'Courier New', monospace"
          }}>
            Welcome back
          </h1>
          <p style={{
            color: "#ff00ff",
            fontSize: "15px",
            textShadow: "0 0 10px rgba(255, 0, 255, 0.5)"
          }}>
            Log in to your account
          </p>
        </div>

        {/* Email Field */}
        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#00ffff",
            marginBottom: "8px",
            textShadow: "0 0 5px rgba(0, 255, 255, 0.5)"
          }}>
            Email address
          </label>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid rgba(255, 0, 255, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 0, 0, 0.5)",
              color: "#00ffff"
            }}
          />
        </div>

        {/* Password Field */}
        <div style={{ marginBottom: "16px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#00ffff",
            marginBottom: "8px",
            textShadow: "0 0 5px rgba(0, 255, 255, 0.5)"
          }}>
            Password
          </label>
          <input
            type="password"
            placeholder="Enter your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid rgba(255, 0, 255, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 0, 0, 0.5)",
              color: "#00ffff"
            }}
          />
        </div>

        {/* Remember + Forgot */}
        <div style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "24px"
        }}>
          <label style={{
            display: "flex",
            alignItems: "center",
            cursor: "pointer",
            fontSize: "14px",
            color: "#ff00ff"
          }}>
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              style={{
                width: "16px",
                height: "16px",
                marginRight: "8px",
                cursor: "pointer",
                accentColor: "#ff00ff"
              }}
            />
            Remember me
          </label>
          <a href="#" style={{
            color: "#00ffff",
            fontWeight: "500",
            fontSize: "14px",
            textDecoration: "none",
            textShadow: "0 0 5px rgba(0, 255, 255, 0.5)"
          }}>
            Forgot password?
          </a>
        </div>

        {/* Sign in button */}
        <button
          onClick={handleLogin}
          disabled={isLoading}
          style={{
            width: "100%",
            background: "linear-gradient(135deg, #ff00ff 0%, #00ffff 100%)",
            color: "#000",
            padding: "14px",
            borderRadius: "8px",
            fontSize: "16px",
            fontWeight: "700",
            border: "none",
            cursor: "pointer",
            transition: "all 0.3s ease",
            boxShadow: "0 0 20px rgba(255, 0, 255, 0.5)",
            textTransform: "uppercase",
            letterSpacing: "2px"
          }}
          onMouseOver={(e) => {
            if (!isLoading) {
              e.target.style.transform = "translateY(-2px)";
              e.target.style.boxShadow = "0 0 30px rgba(255, 0, 255, 0.8), 0 0 50px rgba(0, 255, 255, 0.5)";
            }
          }}
          onMouseOut={(e) => {
            e.target.style.transform = "translateY(0)";
            e.target.style.boxShadow = "0 0 20px rgba(255, 0, 255, 0.5)";
          }}
        >
          {isLoading ? "ACCESSING..." : "LOG IN"}
        </button>

        {/* Divider */}
        <div style={{
          textAlign: "center",
          margin: "24px 0",
          color: "#ff00ff",
          fontSize: "14px",
          position: "relative"
        }}>
          <div style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: "1px",
            background: "linear-gradient(90deg, transparent, rgba(255, 0, 255, 0.5), transparent)"
          }} />
          <span style={{
            position: "relative",
            background: "rgba(0, 0, 0, 0.8)",
            padding: "0 16px"
          }}>
            — Or continue with —
          </span>
        </div>

        {/* Google Sign-In Button */}
        <div
          id="googleSignInDiv"
          style={{
            display: "flex",
            justifyContent: "center",
            marginBottom: "16px"
          }}
        ></div>

        {/* Signup link */}
        <div style={{
          textAlign: "center",
          marginTop: "24px",
          fontSize: "14px",
          color: "#ff00ff"
        }}>
          Don't have an account?{" "}
          <a
            href="/signup"
            style={{
              color: "#00ffff",
              fontWeight: "600",
              textDecoration: "none",
              textShadow: "0 0 5px rgba(0, 255, 255, 0.5)"
            }}
          >
            Sign up here
          </a>
        </div>

        {/* Load Google script */}
        <script src="https://accounts.google.com/gsi/client" async defer></script>
      </div>
    </div>
  );
}
